-- Root-only guarded registration; all source bodies remain private. No provider calls.
BEGIN;
SET LOCAL lock_timeout='15s';SET LOCAL statement_timeout='25s';
DO $register$
DECLARE a population_top3000_202608_202609_v1.acquisition_control%rowtype;c population_top3000_202608_202609_v1.pipeline_control%rowtype;
 expected_tasks constant jsonb := $tasks$[{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-10f27b6d7e87fb60cf87616e","record_count":35},"task_id":"b9935895-685c-433f-8296-2b23fa46288a","source_id":"ctx14-connector-10f27b6d7e87fb60cf87616e","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"10f27b6d7e87fb60cf87616ecd8266323de29e9b592e1fc8e322f70ca48bbc10","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}},{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-368cda5bbd0f9adc9f48cf6c","record_count":35},"task_id":"08d9f40f-5a90-4bb7-9f3e-4b4c0b0371c5","source_id":"ctx14-connector-368cda5bbd0f9adc9f48cf6c","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"368cda5bbd0f9adc9f48cf6cc946f0073470b67fca65731983c9bf19b4ae1f4f","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}},{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-5a666aa84c32037021fc1a52","record_count":43},"task_id":"b539c64c-58fb-4d0c-a60c-3a656092a809","source_id":"ctx14-connector-5a666aa84c32037021fc1a52","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"5a666aa84c32037021fc1a5208dc18ebe28b79349a471d452fccf108c1546e87","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}},{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-8125265f1c4c364af42e4238","record_count":35},"task_id":"28052146-68a8-4563-bca7-8ffed63e1062","source_id":"ctx14-connector-8125265f1c4c364af42e4238","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"8125265f1c4c364af42e4238da8046d2ebe0bee06513769132e1ae79da7b85ec","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}},{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-81dadcae2ea5b6f196ee1f2a","record_count":43},"task_id":"c0067786-7edf-4709-9841-9702964a0e03","source_id":"ctx14-connector-81dadcae2ea5b6f196ee1f2a","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"81dadcae2ea5b6f196ee1f2a3da229f6ff0dd7c53f066616bcc30352675931f2","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}},{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-9ea7c2cdad855204490006f2","record_count":43},"task_id":"3954bb56-c844-4ef5-9cbe-90577efd024d","source_id":"ctx14-connector-9ea7c2cdad855204490006f2","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"9ea7c2cdad855204490006f28cf2d0a330f10e1cb6dc50e9b809b741bdc7ad21","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}},{"payload":{"kind":"CTX14_CONNECTOR_SOURCE_V4","source_id":"ctx14-connector-cb04942787543e510452ded8","record_count":43},"task_id":"17c691b4-d541-49c8-a0c1-5399513e49d3","source_id":"ctx14-connector-cb04942787543e510452ded8","input_versions":{"scope_sha256":"8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd","source_sha256":"cb04942787543e510452ded82adad426325cd08e8ecaa5a61caa8217608f1b40","parser_version":"ctx14-connector-csv-v2","CTX14_contract_sha256":"688f499b22342f8a6fad2b158f17e9049b12b312e648abd19bdca7ba4e1ce592","connector_stage_sha256":"f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2"}}]$tasks$::jsonb;
 q record;j jsonb;actual jsonb;prior_adapters jsonb;new_adapters jsonb;before_control jsonb;after_control jsonb;
 before_pipeline jsonb;after_pipeline jsonb;released jsonb;num integer;wake jsonb;review jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(2026083000261022);
 SELECT * INTO a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'CTX14_V4_CONTROL_MISSING';END IF;
 SELECT * INTO c FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 IF NOT FOUND OR a.owner_id IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR a.owner_fence IS DISTINCT FROM 3 OR a.stop_generation IS DISTINCT FROM 1
 OR a.stopped IS DISTINCT FROM false OR a.enabled IS DISTINCT FROM true OR c.enabled IS DISTINCT FROM true OR a.hold_reason IS NOT NULL
 OR a.admitted_until IS NULL OR a.admitted_until<=clock_timestamp() OR c.deadline IS NULL OR c.deadline<=clock_timestamp() OR c.shared_scheduler_verified IS DISTINCT FROM true
 OR c.expected_owner_id IS DISTINCT FROM a.owner_id OR c.expected_owner_fence IS DISTINCT FROM a.owner_fence OR c.expected_stop_generation IS DISTINCT FROM a.stop_generation
 OR a.scope_sha256 IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR c.scope_sha256 IS DISTINCT FROM a.scope_sha256
 THEN RAISE EXCEPTION 'CTX14_V4_CURRENT_CONTROLLER_REQUIRED';END IF;
 PERFORM population_top3000_202608_202609_v1.d02_daily_resource_guard_v2();
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX14' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE') AND status='LEASED') THEN RAISE EXCEPTION 'CTX14_V4_ACTIVE_ATTEMPT_MUST_FINISH';END IF;
 IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx14_connector_stage_v4(uuid,text)'::regprocedure),'UTF8')),'hex') IS DISTINCT FROM 'f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2'
 OR population_top3000_202608_202609_v1.ctx14_http_bundle_v3() IS DISTINCT FROM '774b504540d44f04eaf00e8c39bd74840e51de4eaf093a782a6e0103c6f079b8'
 THEN RAISE EXCEPTION 'CTX14_V4_REVIEWED_f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2_OR_PRIOR_ROUTE_CHANGED';END IF;
 SELECT details INTO actual FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=12488 AND event='CTX14_SUPPLEMENT_ACTUAL_ROLLBACK_VERIFIED_V4';
 IF NOT FOUND OR encode(sha256(convert_to(actual::text,'UTF8')),'hex') IS DISTINCT FROM 'd1e7d7110a10d7418033e1f1a0de2fc6b999cc753d508635b04066e1bfaaf253'
 OR actual->>'owner_id' IS DISTINCT FROM a.owner_id OR actual->>'owner_fence' IS DISTINCT FROM a.owner_fence::text OR actual->>'stop_generation' IS DISTINCT FROM a.stop_generation::text
 OR actual->>'scope_sha256' IS DISTINCT FROM a.scope_sha256 OR actual->>'result' IS DISTINCT FROM 'PASS_ACTUAL_CTX14_SUPPLEMENT_PROCESSING_ROLLBACK'
 OR actual->>'rows' IS DISTINCT FROM '277' OR actual->>'sources' IS DISTINCT FROM '7' OR actual->>'provider_calls' IS DISTINCT FROM '0'
 OR jsonb_array_length(actual->'stage_proofs') IS DISTINCT FROM 28 OR actual->>'production_changes_rolled_back' IS DISTINCT FROM 'true'
 THEN RAISE EXCEPTION 'CTX14_V4_ACTUAL_ROOT_ROLLBACK_REQUIRED';END IF;
 SELECT jsonb_agg(to_jsonb(pa) ORDER BY stage) INTO prior_adapters FROM population_top3000_202608_202609_v1.pipeline_adapter pa WHERE family_id='CTX14' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE');
 IF jsonb_array_length(prior_adapters) IS DISTINCT FROM 4 THEN RAISE EXCEPTION 'CTX14_V4_PRIOR_ADAPTERS_MISSING';END IF;
 before_control:=to_jsonb(a);before_pipeline:=to_jsonb(c);
 -- Check the exact seven source tasks and immutable source evidence before changing any adapter.
 FOR j IN SELECT value FROM jsonb_array_elements(expected_tasks) LOOP
  IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task t JOIN population_top3000_202608_202609_v1.source_document d ON d.source_id=t.partition_key
    WHERE t.task_id=(j->>'task_id')::uuid AND t.family_id='CTX14' AND t.stage='ACQUIRE' AND t.status='BLOCKED'
    AND t.blocker_code='ENGINEERING_REGISTRATION_REQUIRED' AND t.attempt_id IS NULL AND t.executions=0
    AND t.partition_key=j->>'source_id' AND t.payload=j->'payload' AND t.input_versions=j->'input_versions'
    AND t.input_versions->>'connector_stage_sha256'='f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2'
    AND d.source_sha256=t.input_versions->>'source_sha256' AND d.source_sha256=encode(sha256(convert_to(d.content_text,'UTF8')),'hex')
    AND d.content_bytes=octet_length(d.content_text) AND d.source_provider='Massive connected tool' AND d.source_published_at IS NULL AND d.historical_received_at IS NULL)
  THEN RAISE EXCEPTION 'CTX14_V4_EXACT_HELD_SOURCE_TASK_REQUIRED %',j->>'task_id';END IF;
 END LOOP;
 review:=jsonb_build_object('handler_file_sha256','86985f19b4b1ac4b1cf69e7a503e3ffd13f388a2a894913b4fd0da6fba909551','harness_sha256','b7b262403eb007013f167139fa3600bff6e544c0fdcf333145df474f2fed12ee',
 'source_manifest_sha256','2838da83e7315334e3043ee08d9e1dba6ddf1b5af3c655708742109148550652','staging_file_sha256','06f77a851efda3ae6fd996cf4487122aec3d11587b83132da0db8490e411c166',
 'independent_projection_and_code_review_sha256','93de7efb36b892be1d237dffd208b11016c378dc3a5bfdc7db40f8c63b03cdd9','actual_rollback_event_id',12488,'actual_rollback_details_sha256','d1e7d7110a10d7418033e1f1a0de2fc6b999cc753d508635b04066e1bfaaf253','helper_function_sha256','f0d9613e69b8de529adeda6bb896a2154b6af02217c506c6c68cb54ce0b6f8e2',
 'sources',7,'source_records',277,'provider_calls',0,'all_48_required_source_units_preserved',true,'full_family_accepted',false,'prior_v2_v3_routes_preserved',true);
 FOR q IN SELECT * FROM (VALUES ('ACQUIRE','population_top3000_202608_202609_v1.ctx14_supplement_acquire_v4(uuid,text)','92033999d8ad481341daf4cc3cdbe22779979d2c1429325f5fbff18d6a38bbfe','population_top3000_202608_202609_v1.ctx14_http_acquire_v3(uuid,text)','197401ab5fef0c64eb28b677fd1d8b6173c9d1aa5a9d02f04fc8fc6f57684db9'),('NORMALIZE','population_top3000_202608_202609_v1.ctx14_supplement_normalize_v4(uuid,text)','ce32e609a96fdf36ade2dbf1f5b710d205d1ef4c990e6c789690c7a052fc73f0','population_top3000_202608_202609_v1.ctx14_http_normalize_v3(uuid,text)','e054552fd1bb1d863f2059d7cce3453b3a031f73c3e7b1ad3511bc867570125b'),('DERIVE','population_top3000_202608_202609_v1.ctx14_supplement_derive_v4(uuid,text)','39f209c8c8bd29b50fd213d8f64ab4b651b3a65f1521338712c0d747c74c46eb','population_top3000_202608_202609_v1.ctx14_http_derive_v3(uuid,text)','e936caa046b92827529a32375988f24dccecb6aaf3b26c477b4a535c6a8941ee'),('VALIDATE','population_top3000_202608_202609_v1.ctx14_supplement_validate_v4(uuid,text)','46f81a2cacc5b1e042fbca4be0d395a71e9128817c7aca5c00ab0d8cb26fdcf9','population_top3000_202608_202609_v1.ctx14_http_validate_v3(uuid,text)','46c194507ee23f221665ca87a8d84afeced6db21998ce38d03216199e6b695af')) v(stage,fn,sha,old_fn,old_sha) LOOP
  IF q.sha IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(q.fn::regprocedure),'UTF8')),'hex') THEN RAISE EXCEPTION 'CTX14_V4_WRAPPER_CHANGED %',q.stage;END IF;
  IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_adapter pa WHERE pa.family_id='CTX14' AND pa.stage=q.stage AND pa.function_oid=q.old_fn::regprocedure AND pa.function_sha256=q.old_sha
    AND pa.function_sha256=encode(sha256(convert_to(pg_get_functiondef(pa.function_oid),'UTF8')),'hex')) THEN RAISE EXCEPTION 'CTX14_V4_PRIOR_ADAPTER_CHANGED %',q.stage;END IF;
  UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid=q.fn::regprocedure,function_sha256=q.sha,producer_revision='ctx14-retained-supplement-v4-86985f19b4b1ac4b',enabled=true,
    reviewed_test_evidence=coalesce(reviewed_test_evidence,'{}'::jsonb)||jsonb_build_object('ctx14_retained_supplement_v4',review)
    WHERE family_id='CTX14' AND stage=q.stage;
 END LOOP;
 WITH changed AS (UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='READY',blocker_code=NULL,blocker_until=NULL,resumption_condition=NULL,not_before=clock_timestamp()
   WHERE task_id IN(SELECT (value->>'task_id')::uuid FROM jsonb_array_elements(expected_tasks)) AND status='BLOCKED' AND blocker_code='ENGINEERING_REGISTRATION_REQUIRED'
   RETURNING task_id,partition_key)
 SELECT count(*),jsonb_agg(to_jsonb(changed) ORDER BY partition_key) INTO num,released FROM changed;
 IF num<>7 THEN RAISE EXCEPTION 'CTX14_V4_EXACT_SEVEN_RELEASE_REQUIRED';END IF;
 SELECT jsonb_agg(to_jsonb(pa) ORDER BY stage) INTO new_adapters FROM population_top3000_202608_202609_v1.pipeline_adapter pa WHERE family_id='CTX14' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE');
 SELECT to_jsonb(ac),to_jsonb(pc) INTO after_control,after_pipeline FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
 IF after_control IS DISTINCT FROM before_control OR after_pipeline IS DISTINCT FROM before_pipeline THEN RAISE EXCEPTION 'CTX14_V4_CONTROLS_OR_COUNTERS_CHANGED';END IF;
 PERFORM population_top3000_202608_202609_v1.d02_daily_resource_guard_v2();
 wake:=population_top3000_202608_202609_v1.pipeline_wake_v1(a.owner_id,a.owner_fence,'CTX14 reviewed retained supplement v4 registered; exact seven source tasks released; v2 and v3 routes preserved');
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CTX14_RETAINED_SUPPLEMENT_V4_REGISTERED',jsonb_build_object('owner_id',a.owner_id,'owner_fence',a.owner_fence,'stop_generation',a.stop_generation,'scope_sha256',a.scope_sha256,
 'review',review,'prior_adapters',prior_adapters,'registered_adapters',new_adapters,'released_tasks',released,'wake_receipt',wake,'cumulative_counters_preserved',true,'provider_calls',0,'full_family_accepted',false));
END; $register$;
COMMIT;
